const date=v=>{if(!v)return '미확인';const text=String(v);if(/^\d{4}-\d{2}-\d{2}$/.test(text))return text;const d=new Date(text);return Number.isNaN(d.getTime())?text:new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)+' (KST)'};
