async function loadMaskFiles(files){if(contributionDraft)return;const valid=[];for(const file of Array.from(files||[])){if(file.size>8*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type)){notify('8MB 이하 PNG·JPEG·WebP 사진만 추가할 수 있어요.');continue}if(captureFiles.length+valid.length>=10){notify('사진은 한 번에 10장까지 보낼 수 있어요.');break}valid.push({id:crypto.randomUUID(),file,localUrl:URL.createObjectURL(file),rects:[],uploaded:false})}captureFiles.push(...valid);$('#capture-file').value='';const confirm=$('[name="safeTextConfirmed"]');if(confirm)confirm.checked=false;renderCaptureList();if(valid.length)await selectCapture(valid[0].id)}
