async function maskedBlob(item){const img=new Image();img.src=item.localUrl;await img.decode();if(img.naturalWidth*img.naturalHeight>24000000)throw new Error('사진 크기가 너무 큽니다. 해당 사진을 줄여서 다시 추가해 주세요.');const canvas=document.createElement('canvas');canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0);ctx.fillStyle='#000';for(const r of item.rects)ctx.fillRect(r.x,r.y,r.w,r.h);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));canvas.width=canvas.height=0;if(!blob||blob.size>8*1024*1024)throw new Error('가린 사진이 8MB를 넘거나 저장할 수 없습니다. 사진 크기를 줄여 주세요.');return blob}
async function submitContribution(form){const button=$('#submit-contribution'),out=$('#contribution-status');if(button.disabled)return;const submissionFields=Object.fromEntries(new FormData(form));button.disabled=true;$('#contribution-fields').disabled=true;out.className='';try{if(!contributionDraft){if(!form.safeTextConfirmed.checked)throw new Error('설명과 사진에 개인정보가 없는지 확인해 주세요.');out.textContent='사진을 준비하고 있어요.';for(const item of captureFiles){if(item.invalid)throw new Error('열 수 없는 사진이 있어요. 해당 사진을 삭제하고 다시 추가해 주세요.');item.blob=await maskedBlob(item)}const fields=submissionFields,prefill=state.contributionPrefill||{};const term=state.proposalTab==='term';const values={...prefill,...(!term?{provider:(fields.screenProvider||'').trim(),task:fields.screenTask||'',language:fields.screenLanguage||'',workId:fields.screenTask===prefill.task?prefill.workId||'':''}:{}),proposalType:term?'term':'screen',text:fields.text||'',sourceUrl:fields.sourceUrl,title:(term?fields.termEnglish:fields.text).trim().split('\n')[0].slice(0,100),kind:term?'translation_issue':captureFiles.length?'screen':(prefill.kind==='translation_issue'?'screen':prefill.kind||'screen'),privacyConfirmed:form.safeTextConfirmed.checked,...(!term&&prefill.proposalType==='term'?{referenceId:'',collectionReferenceId:''}:{}),...(term?{termEnglish:fields.termEnglish,termKorean:fields.termKorean,termTarget:fields.termTarget,language:fields.termLanguage,referenceId:prefill.kind==='translation_issue'?prefill.referenceId||'':'',collectionReferenceId:'',workId:''}:{})};const result=await post('createSubmission',values);contributionDraft={id:result.item.id,item:result.item};$$('[data-proposal-tab]').forEach(b=>b.disabled=true);$('#contribution-fields').disabled=true}for(let i=0;i<captureFiles.length;i++){const item=captureFiles[i];if(item.uploaded)continue;out.textContent=`사진을 보내고 있어요. ${i+1} / ${captureFiles.length}`;const data=new FormData();data.set('action','upload');data.set('submissionId',contributionDraft.id);data.set('role','masked');data.set('clientUploadId',item.id);data.set('file',item.blob,'screenshot-'+(i+1)+'.png');const result=await fetchJSON('/api/wgss',{method:'POST',body:data});contributionDraft.item=result.item;item.uploaded=true;item.blob=null}out.textContent=`접수되었습니다. 담당자가 검토한 뒤 게시합니다. 사진 ${captureFiles.length}장 · 접수번호 ${contributionDraft.id}`;button.textContent='새 자료 보내기';button.type='button';button.dataset.action='new-contribution';clearCaptureFiles();$('#capture-list').innerHTML='';$('#mask-editor').hidden=true;notify('자료를 받았습니다. 운영자가 검토할게요.')}catch(e){out.className='error';out.textContent=contributionDraft?`접수번호 ${contributionDraft.id} · 사진 ${captureFiles.filter(x=>x.uploaded).length}/${captureFiles.length}장 전송됨. ${e.message} ‘이어서 보내기’를 누르면 남은 사진을 보냅니다.`:e.message;if(contributionDraft)button.textContent='이어서 보내기';else $('#contribution-fields').disabled=false}finally{button.disabled=false}}
function bindCanvas(c){let start=null;const point=e=>{const r=c.getBoundingClientRect();return {x:Math.max(0,Math.min(c.width,(e.clientX-r.left)*c.width/r.width)),y:Math.max(0,Math.min(c.height,(e.clientY-r.top)*c.height/r.height))}};const rect=p=>({x:Math.min(start.x,p.x),y:Math.min(start.y,p.y),w:Math.abs(p.x-start.x),h:Math.abs(p.y-start.y)});c.onpointerdown=e=>{if(contributionDraft||$('#submit-contribution')?.disabled)return;start=point(e);c.setPointerCapture(e.pointerId);e.preventDefault()};c.onpointermove=e=>{if(start&&!contributionDraft&&!$('#submit-contribution')?.disabled)drawMask(rect(point(e)))};c.onpointerup=e=>{if(contributionDraft||$('#submit-contribution')?.disabled){start=null;return}if(!start)return;const r=rect(point(e));if(r.w>1&&r.h>1)maskState.rects.push(r);start=null;drawMask()};c.onpointercancel=()=>{start=null;drawMask()}}

function inventoryRows(){
 const term=state.inventoryType==='terms',q=normalizeQuery(state.inventoryQuery);
 return (term?state.terms.filter(allowedTerm):state.catalog.screens).filter(r=>(!state.inventoryLanguage||WGSSLanguages.matches(r.language,state.inventoryLanguage))&&(!q||(term?['english','korean','target','source']:['title','stageLabel','provider','id']).some(key=>normalizeQuery(r[key]).includes(q))));
}
function renderInventory(){
 $('#admin-panel').innerHTML=`<div class="result-head"><h2>현재 레퍼런스 목록</h2><p>${state.catalog.screens.length.toLocaleString()}개 화면 · ${WGSSAbout.metrics(state.catalog,state.terms).dictionaryRows.toLocaleString()}쌍 용어</p></div><div class="inventory-types" aria-label="자료 종류">${[['screens','화면'],['terms','용어']].map(([id,label])=>`<button type="button" class="task-button" data-inventory-type="${id}" aria-pressed="${state.inventoryType===id}">${label}</button>`).join('')}</div><div class="inventory-filters"><div class="field"><label for="inventory-query">자료 검색</label><input id="inventory-query" type="search" value="${esc(state.inventoryQuery)}" placeholder="${state.inventoryType==='terms'?'한국어·영어·대응 표현':'회사·화면 이름'}"></div><div class="field"><label for="inventory-language">언어</label><select id="inventory-language">${optionList(state.catalog.languages,state.inventoryLanguage,'모든 언어')}</select></div></div><div id="inventory-results" aria-live="polite"></div>`;
 renderInventoryResults();if(state.inventoryType==='terms')loadTerms();
}
function renderInventoryResults(){
 const node=$('#inventory-results');if(!node)return;
 const term=state.inventoryType==='terms',rows=inventoryRows(),pager=pagination(rows.length),start=(state.page-1)*18;
 node.innerHTML=`<p class="inventory-count">검색 결과 ${rows.length.toLocaleString()}${term?'쌍':'개'}${term&&state.loadingTerms?' · 용어 불러오는 중':''}</p>${term&&state.termsError?'<p class="error">일부 용어를 불러오지 못했습니다. <button type="button" class="text-button" data-action="retry-terms">다시 불러오기</button></p>':''}${rows.slice(start,start+18).map(r=>term?`<article class="list-row"><div><h3>${esc(r.english)}</h3><p>${esc(r.korean||'')} · <span lang="${esc(r.language)}" dir="auto">${esc(r.target)}</span></p><p class="meta">${esc(labelFor('languages',r.language))} · ${esc(state.catalog.dictionary.datasets.find(d=>d.id===r.datasetId)?.name||'검토 후 추가된 용어')}</p></div><button type="button" class="button secondary" data-inventory-term="${esc(r.id)}">자료 확인</button></article>`:`<article class="list-row"><div><h3>${esc(r.provider)} · ${esc(r.stageLabel||r.title)}</h3><p class="meta">${esc(labelFor('languages',r.language))} · ${esc(sourceKindLabel(r.sourceKind))} · 수집 ${date(r.collectedAt)}</p><p class="meta">${esc(r.id)}</p></div><button type="button" class="button secondary" data-screen="${esc(r.id)}">자료 확인</button></article>`).join('')}${!rows.length?`<p class="empty">${term&&state.loadingTerms?'용어를 불러오고 있습니다.':'검색된 자료가 없습니다.'}</p>`:''}${pager}`;
}
function openInventoryTerm(id){
 const r=state.terms.find(r=>r.id===id&&allowedTerm(r));if(!r)return;
 openDialog('용어 자료',`<h3>${esc(r.english)}</h3><dl class="provenance"><dt>한국어</dt><dd>${esc(r.korean||'—')}</dd><dt>${esc(labelFor('languages',r.language))}</dt><dd lang="${esc(r.language)}" dir="auto">${esc(r.target)}</dd><dt>출처</dt><dd>${esc(state.catalog.dictionary.datasets.find(d=>d.id===r.datasetId)?.name||r.source||'검토 후 추가된 용어')}</dd>${safeUrl(r.sourceUrl)?`<dt>원출처</dt><dd>${link(r.sourceUrl)}</dd>`:''}<dt>자료 ID</dt><dd>${esc(r.id)}</dd></dl><div class="actions"><button type="button" class="text-button" data-term-propose="${esc(r.id)}">수정 제안</button><button type="button" class="text-button" data-row-export="${esc(r.id)}">JSON 내려받기</button></div>`);
}
let inventoryQueryTimer;
document.addEventListener('click',e=>{const b=e.target.closest('[data-inventory-type],[data-inventory-term]');if(!b)return;if(b.dataset.inventoryType){state.inventoryType=b.dataset.inventoryType;state.page=1;renderInventory();}else openInventoryTerm(b.dataset.inventoryTerm)});
document.addEventListener('input',e=>{if(e.target.id==='inventory-query'){clearTimeout(inventoryQueryTimer);state.inventoryQuery=e.target.value;state.page=1;inventoryQueryTimer=setTimeout(renderInventoryResults,180)}});
document.addEventListener('change',e=>{if(e.target.id==='inventory-language'){state.inventoryLanguage=e.target.value;state.page=1;renderInventoryResults()}});

async function renderAdmin(){const app=$('#app');app.innerHTML=`<section class="intro"><h1>자료 관리</h1><p>제안을 검토하고, 등록된 자료와 변경 이력을 확인하세요.</p></section><div id="admin-content" class="loading">자료 관리에 연결하는 중입니다.</div>`;try{state.session=await api('session');if(state.route!=='admin'||!$('#admin-content'))return;if(state.session.role!=='admin'&&state.session.publicReview!==true){$('#admin-content').innerHTML=`<div class="empty"><h3>자료 관리에 연결하지 못했습니다.</h3><p>현재 서버에서 제안 검토를 열 수 없습니다. 잠시 후 다시 시도해 주세요.</p><button type="button" class="button secondary" data-action="retry">다시 연결하기</button></div>`;return}$('#admin-content').className='';$('#admin-content').innerHTML=`<div class="admin-nav" role="tablist" aria-label="관리 메뉴">${[['inbox','제안 검토'],['inventory','자료 목록'],['audit','변경 이력']].map(([id,l])=>`<button role="tab" id="admin-tab-${id}" data-admin-tab="${id}" aria-controls="admin-panel" tabindex="${state.adminTab===id?0:-1}" aria-selected="${state.adminTab===id}">${l}</button>`).join('')}</div><div id="admin-panel" role="tabpanel" tabindex="0" aria-labelledby="admin-tab-${state.adminTab}"></div>`;await renderAdminPanel()}catch(e){const node=$('#admin-content');if(node)node.innerHTML=errorMarkup(e.message)}}
async function renderAdminPanel(){const panel=$('#admin-panel');if(!panel)return;panel.innerHTML='<p class="loading">자료를 불러오는 중입니다.</p>';try{if(state.adminTab==='inbox'){const data=await api('submissions');state.adminItems=arr(data.items);const items=state.adminFilter==='all'?state.adminItems:state.adminItems.filter(x=>x.status===state.adminFilter);panel.innerHTML=`<div class="result-head"><h2>새 자료와 수정 제안</h2><p>${items.length}개 · 승인 전 자료는 기존 레퍼런스 검색에 합치지 않습니다.</p></div><div class="field provider-select"><label for="admin-status-filter">검토 상태</label><select id="admin-status-filter">${[['all','모든 상태'],['pending','검토 대기'],['held','보류'],['approved','승인'],['rejected','반려']].map(([v,l])=>`<option value="${v}" ${v===state.adminFilter?'selected':''}>${l}</option>`).join('')}</select></div>${items.length?items.map(item=>`<article class="list-row"><div><span class="status ${esc(item.status)}">${esc(statusNames[item.status]||item.status)}</span><h3>${esc(item.title)}</h3><p class="meta">${item.current?.proposalType==='term'||(!item.current?.proposalType&&item.kind==='translation_issue'&&!state.catalog.phrases.some(p=>p.id===item.current?.referenceId)&&!screenById(item.current?.referenceId))?'용어':'화면'} · 접수 ${date(item.createdAt)} · 첨부 ${arr(item.files).length}개</p><p>${esc((item.current?.text||'').slice(0,160))}</p></div><button class="button secondary" ${item.status==='approved'?'data-approved-review':'data-review'}="${esc(item.id)}">${item.status==='approved'?'승인 내역 보기':'검토하기'}</button></article>`).join(''):'<p class="empty">이 상태의 제안이 없습니다.</p>'}`;return}if(state.adminTab==='inventory'){renderInventory();return}if(state.adminTab==='audit'){const {items=[]}=await api('audit');panel.innerHTML=`<h2>변경 이력</h2>${items.length?items.map(a=>`<article class="list-row"><div><h3>${esc(a.action)}</h3><p class="meta">${esc(date(a.createdAt))} · ${esc(a.actorId)} · ${esc(a.entityId)}</p><details><summary>변경 정보</summary><pre class="record-json">${esc(JSON.stringify(a.details,null,2))}</pre></details></div></article>`).join(''):'<p class="empty">변경 이력이 없습니다.</p>'}`}}catch(e){panel.innerHTML=errorMarkup(e.message)}}
function openApprovedSubmission(item){state.reviewItem=null;const c=item.current||{},files=arr(item.files).filter(f=>f.role==='masked'),base=window.WGSSPublic?.config?.intakeBase||'';openDialog('승인 내역',`<p class="context-note">승인된 자료입니다. 접수 내용과 변경 이력을 확인할 수 있습니다.</p><h3>${esc(item.title)}</h3><dl class="provenance"><dt>검토 상태</dt><dd>승인</dd><dt>접수일</dt><dd>${date(item.createdAt)}</dd>${item.updatedAt?`<dt>최근 처리</dt><dd>${date(item.updatedAt)}</dd>`:''}${c.provider?`<dt>회사</dt><dd>${esc(c.provider)}</dd>`:''}${c.language?`<dt>언어</dt><dd>${esc(labelFor('languages',c.language))}</dd>`:''}${c.sourceUrl?`<dt>출처</dt><dd>${link(c.sourceUrl)}</dd>`:''}${c.termEnglish?`<dt>영어 원문</dt><dd>${esc(c.termEnglish)}</dd>`:''}${c.termTarget?`<dt>대응 표현</dt><dd>${esc(c.termTarget)}</dd>`:''}${c.termKorean?`<dt>한국어 뜻</dt><dd>${esc(c.termKorean)}</dd>`:''}</dl>${c.text?`<h3>접수 내용</h3><p class="approved-description">${esc(c.text)}</p>`:''}${files.length?`<section class="approved-photos" aria-label="승인된 첨부 사진">${files.map((file,i)=>`<figure><img src="${esc(base+'/api/wgss?resource=file&id='+encodeURIComponent(file.id))}" alt="개인정보를 가린 첨부 사진 ${i+1}" loading="lazy"><figcaption>사진 ${i+1}</figcaption></figure>`).join('')}</section>`:''}<button type="button" class="text-button" data-versions="${esc(item.id)}">변경 이력 보기</button><div id="version-history"></div>`)}
function openReview(id){const item=state.adminItems.find(x=>x.id===id);if(item)return item.status==='approved'?openApprovedSubmission(item):WGSSReview.open(item)}
function route(){const hash=location.hash.slice(1).split('?')[0];if(state.route==='contribute'&&hash!=='contribute')clearCaptureFiles();state.route=hash==='about-how'?'about':hash||(initialExplore?'screens':'about');if(state.route==='saved'){state.route='screens';history.replaceState(null,'',location.pathname+location.search+'#screens');}if(!['about','screens','contribute','admin'].includes(state.route))state.route='about';$$('[data-nav]').forEach(a=>a.setAttribute('aria-current',a.dataset.nav===state.route?'page':'false'));if(!state.catalog)return;if(state.route==='about'){WGSSAbout.render();if(hash==='about-how')requestAnimationFrame(()=>$('#about-how')?.scrollIntoView({block:'start'}));}else if(state.route==='screens')renderExplore();else if(state.route==='contribute'){renderContribution(state.prefill||{});state.prefill=null;}else renderAdmin()}
function beginContribution(prefill){state.prefill=prefill;if(location.hash==='#contribute'){renderContribution(prefill,true);state.prefill=null}else location.hash='contribute'}
function proposeReference(id){const r=screenById(id);if(!r)return;$('#detail-dialog').close();beginContribution({kind:'translation_issue',title:r.provider+' 문구·출처 수정 제안',provider:r.provider,language:r.language,country:r.country,task:taskName(r.taskId),purpose:r.purpose,stage:r.stage,sourceUrl:r.sourceUrl,referenceId:r.id})}
async function busy(button,fn){if(button)button.disabled=true;try{await fn()}catch(e){if(button?.closest('#review-form')&&typeof WGSSReview!=='undefined')WGSSReview.showError(e.message);else notify(e.message)}finally{if(button&&button.isConnected)button.disabled=false}}
function sourceOverview(){return WGSSDictionary.sourceOverview()}
async function boot(){try{const [catalogResult,sessionResult]=await Promise.allSettled([fetchJSON('/integration-data/catalog.json'),api('session')]);if(catalogResult.status==='rejected')throw catalogResult.reason;state.catalog=catalogResult.value;state.session=sessionResult.status==='fulfilled'?sessionResult.value:null;state.catalogIdentity=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(state.catalog))).then(b=>[...new Uint8Array(b)].map(v=>v.toString(16).padStart(2,'0')).join(''));WGSSApplied.initialize(state.catalog);const oldLanguage=state.language;state.language=WGSSLanguages.filter(state.language);if(!state.catalog.languages.some(l=>l.id===state.language))state.language='';if(oldLanguage!==state.language)syncURL();const queryTask=state.catalog.tasks.find(t=>[t.label,...arr(t.aliases)].some(a=>normalizeQuery(a)===normalizeQuery(state.query)));if(state.query&&queryTask&&state.task&&queryTask.id!==state.task){state.task='';syncURL();}let refreshFailed=false;try{await WGSSApplied.refresh()}catch{refreshFailed=true;}if(!['all','phrases','terms'].includes(state.wordMode))state.wordMode='all';if(!['screens','words','features'].includes(state.tab))state.tab='screens';route();if(state.route==='screens')syncURL();if(state.route==='screens'&&initial.get('reference')&&screenById(initial.get('reference')))openScreen(initial.get('reference'));else if(state.route==='screens'&&initial.get('phrase'))openPhrase(initial.get('phrase'));if(refreshFailed)notify('최신 승인 자료를 불러오지 못했습니다. 기본 자료를 표시합니다. 새로고침해 주세요.');}catch(e){$('#app').innerHTML=`<section class="intro"><h1>레퍼런스를 불러오지 못했습니다.</h1></section>${errorMarkup(e.message)}`}}
window.addEventListener('hashchange',route);
$('#detail-dialog').addEventListener('close',()=>{const u=new URL(location.href);u.searchParams.delete('reference');u.searchParams.delete('phrase');history.replaceState(null,'',u);if(lastFocus?.isConnected)lastFocus.focus()});
document.addEventListener('click',async e=>{const target=e.target.closest('button,a,summary');if(!target)return;const d=target.dataset;if(d.captureEdit){await selectCapture(d.captureEdit);return}if(d.captureRemove){if(contributionDraft)return;const item=captureFiles.find(x=>x.id===d.captureRemove);if(item){URL.revokeObjectURL(item.localUrl);captureFiles=captureFiles.filter(x=>x!==item);if(maskState?.item===item){maskState=null;$('#mask-editor').hidden=true}renderCaptureList();$('[name="safeTextConfirmed"]').checked=false}return}if(d.wordJump){e.preventDefault();$('#'+d.wordJump)?.scrollIntoView({block:'start'});return}if(d.termPage){state.termPage=Number(d.termPage);renderWords();$('#dictionary-results')?.scrollIntoView({block:'start'});return}if(d.removeFilter){state[d.removeFilter]='';state.page=1;state.termPage=1;syncURL();renderExplore();return}
 if('close'in d){$('#detail-dialog').close();return}if(d.task){clearTimeout(queryTimer);state.query='';state.task=state.task===d.task?'':d.task;state.page=1;state.termPage=1;syncURL();renderExplore();return}if(d.tab){state.tab=d.tab;state.page=1;syncURL();renderExplore();if(d.tab==='words'&&state.wordMode!=='phrases')loadTerms();return}if(d.screen){openScreen(d.screen);return}if(d.flow){openScreen(d.flow,true);return}if(d.page){state.page=Number(d.page);if(state.route==='admin'){if(state.adminTab==='inventory')renderInventoryResults();else renderAdminPanel();}else renderResults();$('#main').scrollIntoView({block:'start'});return}if(d.propose){proposeReference(d.propose);return}if(d.phrasePropose||d.termPropose){$('#detail-dialog').close();const p=d.phrasePropose?state.catalog.phrases.find(x=>x.id===d.phrasePropose):state.terms.find(x=>x.id===d.termPropose);if(!p){notify('원본 항목을 찾을 수 없습니다.');return}beginContribution({proposalType:d.termPropose?'term':'screen',termEnglish:p.english||'',termKorean:p.korean||'',termTarget:p.target||'',kind:'translation_issue',title:'문구 수정 제안',text:'원문: '+(p.text||p.target||p.english)+'\n수정안: \n근거: ',provider:p.provider,language:p.language,country:p.country,sourceUrl:p.sourceUrl,referenceId:p.id});return}if(d.addCollectionScreen){WGSSApplied.addCollectionScreen(d.addCollectionScreen);return}if(d.screenUpdate){const r=screenById(d.screenUpdate);if(!r)return;$('#detail-dialog').close();beginContribution({kind:'screen',title:r.provider+' 화면 업데이트 제안',text:'변경 내용: \n관찰 범위: ',provider:r.provider,language:r.language,country:r.country,task:taskName(r.taskId),purpose:r.purpose,stage:r.stage,referenceId:r.id});return}if(d.workDefinition){const w=state.catalog.canonicalWorks.find(w=>w.id===d.workDefinition);if(w)openDialog(w.label,`<p>${esc(w.definition)}</p><dl class="provenance"><dt>업무 ID</dt><dd>${esc(w.id)}</dd><dt>행위자</dt><dd>${esc(known(w.actorRole))}</dd><dt>대상</dt><dd>${esc(known(w.objectKey))}</dd><dt>결과</dt><dd>${esc(known(w.outcomeKey))}</dd></dl><p class="note">기존 업무 정의를 보존합니다. 회사별 기능 제공·실제 화면·전체 MECE 승인은 별도입니다.</p>`);return}if(d.phraseDetail){openPhrase(d.phraseDetail);return}if(d.rowExport){const row=state.catalog.phrases.find(x=>x.id===d.rowExport)||state.terms.find(x=>x.id===d.rowExport);if(row)downloadJSON({schema:'wgss-source-row/v1',record:row,sourceCatalog:{schemaVersion:state.catalog.schemaVersion,dictionaryRelease:state.catalog.dictionary.release},advisory:'출처 행·번역 상태·권리 조건을 보존하고 의미 동치를 추정하지 마세요.'},'wgss-row.json');return}if(d.copyReference){await busy(target,async()=>{await navigator.clipboard.writeText(location.href);notify('현재 근거의 링크를 복사했습니다.')});return}if(d.evidenceExport){exportEvidence({name:'화면 근거',referenceIds:[d.evidenceExport],context:{type:'single-reference'}});return}if(d.provenance){await busy(target,async()=>{const row=state.terms.find(r=>r.id===d.provenance);const data=await fetchJSON(row.provenancePath);const raw=arr(data.rows).find(x=>x.id===row.id||x.evidence_id===row.id)||data;openDialog('원천 행 근거',`<p class="note">행 ID ${esc(row.id)} · ${esc(row.sourceConceptId)}</p><pre class="record-json">${esc(JSON.stringify(raw,null,2))}</pre>`)});return}if(d.adminTab){if(!['inbox','inventory','audit'].includes(d.adminTab))return;state.adminTab=d.adminTab;state.page=1;renderAdmin();return}if(d.approvedReview){const item=state.adminItems.find(x=>x.id===d.approvedReview);if(item)openApprovedSubmission(item);return}if(d.review){openReview(d.review);return}if(d.versions){await busy(target,async()=>{const j=await fetchJSON('/api/wgss?resource=versions&id='+encodeURIComponent(d.versions));$('#version-history').innerHTML=arr(j.items).map(v=>`<article class="list-row"><div><h3>버전 ${v.version} · ${esc(v.title)}</h3><p class="meta">${esc(date(v.createdAt))} · ${esc(statusNames[v.status]||known(v.status))}</p>${v.reviewReason?`<p>검토 사유: ${esc(v.reviewReason)}</p>`:''}<pre class="record-json">${esc(JSON.stringify(v.content,null,2))}</pre></div></article>`).join('')||'<p class="note">저장된 버전이 없습니다.</p>'});return}
 const action=d.action;if(!action)return;if(action==='new-contribution'){renderContribution({proposalType:state.proposalTab},true);return}if(action==='add-search-material'){addSearchMaterial(d.kind);return}if(action==='retry-terms'){state.termsError=false;loadTerms();return}if(action==='retry'){location.reload();return}if(action==='clear-constraints'){for(const k of ['task','country','language','provider'])state[k]='';state.page=1;state.termPage=1;syncURL();renderExplore();return}if(action==='clear-filters'){for(const k of ['task','query','country','language','provider'])state[k]='';state.page=1;syncURL();renderExplore();return}if(action==='undo-mask'){maskState?.rects.pop();drawMask();return}if(action==='add-mask-coordinates'){if(!maskState)return;const [x,y,w,h]=['x','y','w','h'].map(k=>Number($('#mask-'+k).value));if(w<=0||h<=0||x<0||y<0||x+w>maskState.width||y+h>maskState.height){notify('원본 이미지 안에 있는 유효한 좌표와 크기를 입력하세요.');return}maskState.rects.push({x,y,w,h});drawMask();return}if(action==='refresh-admin'){renderAdminPanel();return}if(action==='market-scan'){await busy(target,async()=>{notify('저장된 공식 URL 조사를 실행하고 있습니다.');const result=await post('runMarketScan');notify(result.job?.status==='failed'?'조사 작업이 실패했습니다. 작업 기록에서 사유를 확인하세요.':'조사 실행 결과를 작업 기록에 저장했습니다.');state.adminTab='jobs';renderAdmin()});return}if(action==='source-overview'){sourceOverview();return}if(action==='screen-metadata'){const r=screenById(d.id);openDialog('원본의 식별 정보',`<pre class="record-json">${esc(JSON.stringify(r,null,2))}</pre>`);return}
});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.filter){state[t.dataset.filter]=t.value;state.page=1;state.termPage=1;syncURL();renderResults();if(state.tab==='words'&&state.wordMode!=='phrases')loadTerms();return}if(t.name==='word-mode'){state.wordMode=t.value;state.page=1;state.termPage=1;syncURL();renderWords();if(t.value!=='phrases')loadTerms();return}if(t.id==='capture-file'){loadMaskFiles(t.files);return}if(t.id==='admin-status-filter'){state.adminFilter=t.value;renderAdminPanel();return}});
let queryTimer;document.addEventListener('input',e=>{if(e.target.id==='query'){clearTimeout(queryTimer);queryTimer=setTimeout(()=>{updateSearchQuery(e.target.value)},180)}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.id)return;e.preventDefault();if(form.id==='search-form'){clearTimeout(queryTimer);updateSearchQuery($('#query').value);return}if(form.id==='contribution-form'){submitContribution(form);return}if(form.id==='review-form'){await busy(e.submitter,async()=>{if(form.hasAttribute('data-review-redesign'))WGSSReview.validateDecision(form,e.submitter.value);const values=Object.fromEntries(new FormData(form)),maskedFileIds=new FormData(form).getAll('maskedFileIds').filter(Boolean),decision=e.submitter.value;if(decision==='approved'&&(!form.privacyReviewed.checked||!form.readabilityReviewed.checked))throw new Error('승인하려면 개인정보와 가독성을 직접 검토한 항목을 체크하세요.');await post('reviewSubmission',{id:state.reviewItem.id,expectedVersion:state.reviewItem.version,decision,reason:values.reason,privacyReviewed:form.privacyReviewed.checked,readabilityReviewed:form.readabilityReviewed.checked,maskedFileIds,...(decision==='approved'?{application:WGSSApplied.application(form)}:{})});if(decision==='approved')await WGSSApplied.refresh();notify(decision==='approved'?'승인한 내용을 해당 자료에 반영했습니다.':'검토 결정을 저장했습니다.');$('#detail-dialog').close();renderAdminPanel()});return}if(form.id==='version-form'){await busy(e.submitter,async()=>{await post('createVersion',{id:state.reviewItem.id,expectedVersion:state.reviewItem.version,...Object.fromEntries(new FormData(form))});notify('새 수정 버전을 만들었습니다. 다시 검토해야 합니다.');$('#detail-dialog').close();renderAdminPanel()});return}if(form.id==='ai-review-form'){await busy(e.submitter,async()=>{const out=$('#ai-status');out.textContent='승인 범위를 확인하고 AI 검토를 실행 중입니다. 결과를 받을 때까지 기다려 주세요.';const result=await post('runAiJob',{submissionId:state.reviewItem.id,...Object.fromEntries(new FormData(form))});out.innerHTML=`<p>${result.job?.status==='failed'?'작업 실패':'작업 완료'}</p><pre class="record-json">${esc(JSON.stringify(result.job?.result||result.job?.error,null,2))}</pre>`});return}if(form.id==='settings-form'){await busy(e.submitter,async()=>{const values=Object.fromEntries(new FormData(form));await post('updateSettings',{settings:{sourceUrls:values.sourceUrls.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),marketQuery:values.marketQuery,model:values.model,intervalHours:Number(values.intervalHours),scheduleEnabled:form.scheduleEnabled.checked}});$('#settings-status').textContent='설정을 저장했습니다. 현재 실행 방식은 조사 설정 상단에서 확인할 수 있습니다.'});return}});
boot();
document.addEventListener('keydown',e=>{if(e.target.matches('[data-tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){const tabs=$$('[data-tab]');let i=tabs.indexOf(e.target);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;e.preventDefault();tabs[i].click();$('[data-tab="'+tabs[i].dataset.tab+'"]').focus()}});
function downloadJSON(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function openPhrase(id){
 const p=state.catalog.phrases.find(x=>x.id===id);if(!p)return;
 const screens=arr(p.screenIds).map(screenById).filter(Boolean),admin=state.route==='admin';
 openDialog('문구와 화면 보기',`${WGSSApplied.badge(p)}<h3 class="word-text">${esc(p.text)}</h3><div class="dialog-layout phrase-detail-layout">${p.imagePath?`<div class="original">${imageHTML(p)}</div>`:''}<div>${provenance(p)}<dl class="provenance"><dt>문구 역할</dt><dd>${esc(phraseRoleLabel(p.role))}</dd>${publicValue(p.context)?`<dt>사용 맥락</dt><dd>${esc(p.context)}</dd>`:''}${screens.length?`<dt>연결 화면</dt><dd>${screens.map(r=>`<button class="text-button" data-screen="${esc(r.id)}">${esc(r.stageLabel||r.title)}</button>`).join(' ')}</dd>`:''}</dl><div class="actions">${admin?`<button class="text-button" data-row-export="${esc(id)}">문구 내려받기 (JSON)</button><button class="text-button" data-copy-reference="${esc(id)}">이 문구 링크 복사</button>`:''}<button class="text-button" data-phrase-propose="${esc(id)}">수정 제안</button></div></div></div>`);
 const u=new URL(location.href);u.searchParams.set('phrase',id);u.searchParams.delete('reference');history.replaceState(null,'',u);
}

document.addEventListener('keydown',e=>{if(e.target.matches('[data-admin-tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){const tabs=$$('[data-admin-tab]');let i=tabs.indexOf(e.target);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;e.preventDefault();const next=tabs[i].dataset.adminTab;state.adminTab=next;state.page=1;renderAdmin().then(()=>$('[data-admin-tab="'+next+'"]')?.focus())}});

document.addEventListener('click',e=>{const t=e.target.closest('[data-proposal-tab]');if(t)changeProposalTab(t.dataset.proposalTab)});
